
import Vue from 'vue';
import store from '../index'

const state = () => ({
    // 用户信息
    userInfo: '',
    
});

const getters = {};


const actions = {};


const mutations = {
    ['USER_INFO'](state, data) {
        state.userInfo = data;
    },
};

export default {
    namespaced: true,
    state,
    getters,
    actions,
    mutations
}