import Vue from 'vue';
import Vuex from 'vuex';

//在vuex初始化时导入插件
import persist from 'vuex-persistedstate';

import User from './modules/user';

Vue.use(Vuex);

//并使用
export default new Vuex.Store({
    modules: {
        User,
    },
    plugins: [
        new persist({
            storage: window.localStorage,
            reducer(val) {
                return {
                    User: val.User,
                };
            }
        })
    ]
});


